import{StepType}from"./Schema.js";import*as PuppeteerReplay from"../../../third_party/puppeteer-replay/puppeteer-replay.js";export function createViewportStep(e){return{type:StepType.SetViewport,width:e.clientWidth,height:e.clientHeight,deviceScaleFactor:1,isMobile:!1,hasTouch:!1,isLandscape:!1}}export function createEmulateNetworkConditionsStep(e){return{type:StepType.EmulateNetworkConditions,...e}}export function areSelectorsEqual(e,t){return"selectors"in e&&"selectors"in t?JSON.stringify(e.selectors)===JSON.stringify(t.selectors):!("selectors"in e)&&!("selectors"in t)}export const minTimeout=1;export const maxTimeout=3e4;export const parse=PuppeteerReplay.parse;export const parseStep=PuppeteerReplay.parseStep;